(()=>{'use strict';
const S={csrf:'',data:null,tab:'dashboard',apps:[],detail:null,users:[],heartbeat:null,notificationTimer:null,updateTimer:null,importTimer:null,importState:null,importOpen:false,routeSeq:0,detailReturn:'/library',pagination:{page:1,perPage:20,total:0,pages:1,from:0,to:0},taxonomy:{total:0,sections:{apps:0,games:0},categories:[],roots:[],fetch:{status:'not_fetched'}},library:{page:1,perPage:20,q:'',section:'all',category:'',sort:'latest'}};
const $=s=>document.querySelector(s),app=$('#app');
const ICONS={home:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M4 11.5 12 4l8 7.5"/><path d="M6 10v9h5v-5h2v5h5v-9"/></svg>',android:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><rect x="7" y="3" width="10" height="18" rx="2"/><path d="M10 6h4M11 18h2"/></svg>',publish:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M12 3v12M7 8l5-5 5 5"/><path d="M5 13v7h14v-7"/></svg>',settings:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7"><circle cx="12" cy="12" r="3"/><path d="M19 13.5v-3l-2-.7-.7-1.7.9-1.9-2.1-2.1-1.9.9-1.7-.7L10.5 2h-3l-.7 2-1.7.7-1.9-.9L1.1 6l.9 1.9-.7 1.7-2 .7v3l2 .7.7 1.7-.9 1.9 2.1 2.1 1.9-.9 1.7.7.7 2h3l.7-2 1.7-.7 1.9.9 2.1-2.1-.9-1.9.7-1.7z" transform="translate(1.5 .5) scale(.86)"/></svg>',plus:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M12 5v14M5 12h14"/></svg>',refresh:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M20 11a8 8 0 1 0-2 5.4"/><path d="M20 5v6h-6"/></svg>',search:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><circle cx="11" cy="11" r="7"/><path d="m21 21-4.5-4.5"/></svg>',bell:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9"/><path d="M10 21h4"/></svg>',menu:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M4 7h16M4 12h16M4 17h16"/></svg>',close:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M6 6l12 12M18 6 6 18"/></svg>',pulse:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M3 12h4l2.5-7 4 14L16 12h5"/></svg>'};
const icon=n=>`<span class="icon">${ICONS[n]||''}</span>`;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const safeUrl=v=>{try{const u=new URL(String(v||''));return /^https?:$/.test(u.protocol)?u.toString():''}catch{return''}};
const fmt=n=>Number(n||0).toLocaleString();
const bytes=n=>{n=Number(n||0);if(!n)return'Not reported';const u=['B','KB','MB','GB'];const i=Math.min(3,Math.floor(Math.log(n)/Math.log(1024)));return`${(n/(1024**i)).toFixed(i?1:0)} ${u[i]}`};
const date=v=>{if(!v)return'—';const d=new Date(v);return Number.isNaN(d.getTime())?String(v):d.toLocaleDateString()};
document.documentElement.dataset.theme='dark';
const themeMeta=document.querySelector('meta[name="theme-color"]');if(themeMeta)themeMeta.content='#000000';
function toast(msg,type='info'){document.querySelectorAll('.toast').forEach(x=>x.remove());const t=document.createElement('div');t.className=`toast toast-${type}`;t.innerHTML=`<span class="toast-mark"></span><div><div class="toast-title">${esc(msg)}</div></div>`;document.body.appendChild(t);setTimeout(()=>t.remove(),3600)}
async function API(url,opts={}){const headers=new Headers(opts.headers||{});if(opts.method&&opts.method!=='GET'&&S.csrf)headers.set('x-csrf-token',S.csrf);if(opts.body&&typeof opts.body==='string'&&!headers.has('content-type'))headers.set('content-type','application/json');const r=await fetch(url,{credentials:'same-origin',...opts,headers});const ct=r.headers.get('content-type')||'';const data=ct.includes('json')?await r.json():await r.text();if(!r.ok){const e=new Error(data?.error||data||`Request failed (${r.status})`);e.status=r.status;e.data=data;throw e}return data}
async function bootstrap(){S.data=await API('/api/bootstrap');S.csrf=S.data.csrfToken;return S.data}
const isAdmin=()=>S.data?.user?.role==='admin';
function profileHtml(){const u=S.data?.user||{};return`<div class="profile-top"><div class="profile-media">${u.avatarUrl?`<img class="profile-avatar" src="${esc(u.avatarUrl)}" alt="">`:`<div class="profile-avatar avatar-fallback">${esc((u.name||u.email||'A').slice(0,1).toUpperCase())}</div>`}</div><div class="profile-main"><div class="profile-name">${esc(u.name||u.email||'User')}</div><div class="profile-email">${esc(u.email||'')}</div><div class="profile-role-row"><span class="profile-role-pill ${u.role==='partner'?'partner':''}">${esc(u.roleLabel||'Partner')}</span></div></div></div><div class="profile-divider"></div><form method="post" action="/logout"><input type="hidden" name="_csrf" value="${esc(S.csrf)}"><button class="profile-signout" title="Sign out">Sign out</button></form>`}
function navItem(key,label,ico,badge=''){return`<button class="nav-btn ${S.tab===key?'active':''}" data-nav="${key}"><span><span class="nav-icon">${icon(ico)}</span>${label}</span>${badge!==''?`<span class="badge">${fmt(badge)}</span>`:''}</button>`}
function shell(){const c=S.data.counts||{};app.innerHTML=`<div class="shell"><aside class="sidebar" id="sidebar"><div class="side-scroll"><div class="brand"><img class="brand-logo" src="/logo.svg" alt="Appbit"><div class="brand-sub">APK Publishing Workspace</div></div><div class="nav-label">Workspace</div>${navItem('dashboard','Dashboard','home')}${navItem('library','App Library','android',c.total)}${navItem('publishing','Publishing','publish',c.published)}${navItem('updates','Update Center','refresh',c.updates)}${isAdmin()?`<div class="nav-label">System</div>${navItem('settings','Settings','settings')}`:''}</div><div class="sidebar-foot"><div class="profile-card">${profileHtml()}</div></div></aside><main class="main"><header class="topbar"><div style="display:flex;gap:10px;align-items:center"><button class="btn icon-btn mobile-menu" id="mobileMenu">${icon('menu')}</button><div><div><span class="top-title" id="topTitle"></span><span class="live"><span class="live-dot"></span>Live Database</span></div><div class="top-sub" id="topSub"></div></div></div><div class="actions"><button class="notification-bell" id="notificationBell" title="Notifications">${icon('bell')}<span class="notification-count ${Number(S.data.notificationSummary?.unreadCount||0)?'show':''}" id="notificationCount">${fmt(S.data.notificationSummary?.unreadCount||0)}</span></button>${isAdmin()?'<button class="btn hide-mobile" id="healthBtn">Health</button>':''}<button class="btn primary" id="newBtn">${icon('plus')} Add APK</button></div></header><div class="content" id="content"></div></main></div>`;bindShell();updateHeader()}
function bindShell(){document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>go(b.dataset.nav));$('#mobileMenu').onclick=()=>$('#sidebar').classList.toggle('open');$('#newBtn').onclick=()=>go('add');$('#notificationBell').onclick=openNotifications;if($('#healthBtn'))$('#healthBtn').onclick=openHealth}
function updateHeader(){const map={dashboard:['Dashboard','Android APK publishing overview'],library:['App Library','All managed Android apps, including public and draft records'],publishing:['Publishing','Apps currently public through Appbit'],updates:['Update Center','Review and control APK update checks'],settings:['Settings','Team, backups, and maintenance'],detail:['App Workspace','Review metadata, media, and publishing'],add:['Add APK','Add an Android app from its source URL']};const m=map[S.tab]||map.dashboard;if($('#topTitle'))$('#topTitle').textContent=m[0];if($('#topSub'))$('#topSub').textContent=m[1];document.querySelectorAll('[data-nav]').forEach(x=>x.classList.toggle('active',x.dataset.nav===(['detail','add'].includes(S.tab)?'library':S.tab)))}
async function refreshBootstrap(){await bootstrap();const c=S.data.counts||{};document.querySelectorAll('[data-nav="library"] .badge').forEach(x=>x.textContent=fmt(c.total));document.querySelectorAll('[data-nav="publishing"] .badge').forEach(x=>x.textContent=fmt(c.published));document.querySelectorAll('[data-nav="updates"] .badge').forEach(x=>x.textContent=fmt(c.updates));const n=$('#notificationCount');if(n){const u=Number(S.data.notificationSummary?.unreadCount||0);n.textContent=fmt(u);n.classList.toggle('show',u>0)}}
async function loadApps(scope='all',q='',opts={}){const page=Math.max(1,Number(opts.page||1)),perPage=Math.max(1,Math.min(100,Number(opts.perPage||20))),section=opts.section||'all',category=opts.category||'',sort=opts.sort||'latest';const ps=new URLSearchParams({scope,q,page:String(page),perPage:String(perPage),section,category,sort});const d=await API(`/api/apps?${ps.toString()}`);S.apps=d.apps||[];S.pagination=d.pagination||{page,perPage,total:S.apps.length,pages:1,from:S.apps.length?1:0,to:S.apps.length};if(d.counts&&S.data)S.data.counts=d.counts;return d}
async function loadTaxonomy(){const d=await API('/api/taxonomy');S.taxonomy={total:Number(d.total||0),sections:d.sections||{apps:0,games:0},categories:Array.isArray(d.categories)?d.categories:[],roots:Array.isArray(d.roots)?d.roots:[],fetch:d.fetch||{status:'not_fetched'}};return S.taxonomy}
async function loadLibrary(){const f=S.library;await Promise.all([loadApps('all',f.q,{page:f.page,perPage:20,section:f.section,category:f.category,sort:f.sort}),loadTaxonomy()]);f.page=S.pagination.page;return S.apps}
function stat(label,num,sub,ico,tab){return`<button class="stat" data-go="${tab}"><div class="stat-head"><span class="stat-icon">${icon(ico)}</span>${esc(label)}</div><div class="stat-num">${fmt(num)}</div><div class="stat-sub">${esc(sub)}</div></button>`}
function stats(){const c=S.data.counts||{};return`<div class="stats">${stat('App Library',c.total,'All managed apps','android','library')}${stat('Public',c.published,'Apps currently published','publish','publishing')}${stat('Updates',c.updates,'Updates waiting for review','refresh','updates')}${stat('Ready',c.ready,'Metadata ready','home','library')}</div>`}
function appRow(x){const meta=x.sourceMeta||{},iconUrl=safeUrl(meta.iconUrl),mod=String(x.modInfo||meta.modInfo||x.apkType||'APK'),rating=x.ratingValue??meta.ratingValue,badge=/premium/i.test(mod)?'PREMIUM':/pro unlocked/i.test(mod)?'PRO':/mod/i.test(mod)?'MOD':x.published?'PUBLIC':String(x.sourceSection||'APP').toUpperCase();return`<article class="app-card ${x.updateAvailable?'update':''}" data-app="${x.id}"><div class="app-card-visual"><span class="app-card-ribbon">${esc(badge)}</span>${x.updateAvailable?'<span class="app-update-dot" title="Update available"></span>':''}${iconUrl?`<img class="app-card-icon" src="/api/apps/${x.id}/media/icon?inline=1" loading="lazy" alt="${esc(x.name)} icon">`:`<div class="app-card-icon logo-fallback">${esc((x.name||'A').slice(0,1))}</div>`}</div><div class="app-card-body"><button class="app-card-name" data-open="${x.id}">${esc(x.name)}</button><div class="app-card-line"><span>v${esc(x.version||'—')}</span><i>•</i><span>${bytes(x.fileSizeBytes)}</span></div><div class="app-card-line app-card-rating"><span class="star">★</span><span>${rating==null?'—':esc(rating)}</span><span class="app-mod">${esc(mod)}</span></div><div class="app-card-category">${esc(x.category||'Other')}</div></div><div class="app-card-footer"><button class="btn primary app-open" data-open="${x.id}">Open</button></div></article>`}
function appPanel(title,sub,items,empty='No apps found.'){return`<section class="panel"><div class="panel-head"><div><div class="panel-title">${esc(title)}</div><div class="panel-sub">${esc(sub)}</div></div></div><div class="app-grid">${items.length?items.map(appRow).join(''):`<div class="empty app-grid-empty">${esc(empty)}</div>`}</div></section>`}
function bindRows(root=document){root.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>openDetail(Number(b.dataset.open)))}
function libraryHref(){const f=S.library,p=new URLSearchParams();if(f.section!=='all')p.set('section',f.section);if(f.category)p.set('category',f.category);if(f.sort!=='latest')p.set('sort',f.sort);if(f.page>1)p.set('page',String(f.page));if(f.q)p.set('q',f.q);return '/library'+(p.toString()?'?'+p:'')}
function restoreLibraryQuery(search){const q=new URLSearchParams(search);S.library.section=['all','apps','games'].includes(q.get('section'))?q.get('section'):'all';S.library.category=q.get('category')||'';S.library.sort=['latest','popular','trending','name'].includes(q.get('sort'))?q.get('sort'):'latest';S.library.page=Math.max(1,Number(q.get('page'))||1);S.library.q=q.get('q')||''}
function setRoute(path,{replace=false,state={}}={}){if(location.pathname+location.search===path)return;history[replace?'replaceState':'pushState']({appbit:true,...state},'',path)}
async function releaseActiveDetail(){const x=S.detail;stopHeartbeat();S.detail=null;if(x?.id){try{await API(`/api/apps/${x.id}/release`,{method:'POST',body:'{}'})}catch{}}}
async function routeLocation(){const path=location.pathname;const match=path.match(/^\/apps\/(\d+)\/?$/);if(match)return openDetail(Number(match[1]),{history:false,returnUrl:history.state?.returnUrl||'/library'});if(path==='/library/add')return go('add',{history:false});const tab=path==='/'?'dashboard':path.replace(/^\//,'');if(tab==='library')restoreLibraryQuery(location.search);return go(tab,{history:false})}
async function go(tab,opts={}){if(tab==='settings'&&!isAdmin())tab='dashboard';if(!['dashboard','library','publishing','updates','settings','add'].includes(tab))tab='dashboard';const seq=++S.routeSeq;if(S.detail)await releaseActiveDetail();S.tab=tab;$('#sidebar')?.classList.remove('open');updateHeader();const path=tab==='dashboard'?'/':tab==='add'?'/library/add':tab==='library'?libraryHref():'/'+tab;if(opts.history!==false)setRoute(path,{replace:opts.replace});const c=$('#content');c.innerHTML='<div class="notice">Loading…</div>';try{if(tab==='dashboard'){await loadApps('all','',{page:1,perPage:20,sort:'latest'});if(seq!==S.routeSeq)return;renderDashboard()}else if(tab==='library'){await loadLibrary();if(seq!==S.routeSeq)return;renderLibrary()}else if(tab==='publishing'){await loadApps('published','',{page:1,perPage:100,sort:'latest'});if(seq!==S.routeSeq)return;renderPublishing()}else if(tab==='updates'){await loadApps('updates','',{page:1,perPage:100,sort:'latest'});if(seq!==S.routeSeq)return;await renderUpdateCenter()}else if(tab==='add')renderImportPage();else await renderSettings()}catch(e){if(seq===S.routeSeq)c.innerHTML=`<div class="notice error">${esc(e.message)}</div>`}}

function renderDashboard(){const recent=S.apps.slice(0,8),updates=S.apps.filter(x=>x.updateAvailable).slice(0,8);$('#content').innerHTML=stats()+appPanel('Recent Apps','Latest Android apps in the workspace.',recent,'No APK apps yet.')+appPanel('Update Watch','Apps with a newer source version.',updates,'No APK updates detected.');document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>go(b.dataset.go));bindRows($('#content'))}
function selectedCategory(){const f=S.library,t=S.taxonomy||{},cats=Array.isArray(t.categories)?t.categories:[];return cats.find(c=>c.section===f.section&&c.slug===f.category)||null}
function libraryToolbar(){const f=S.library,t=S.taxonomy||{},fetch=t.fetch||{},saved=['complete','existing','partial','interrupted'].includes(fetch.status),count=Number(fetch.sourceCategoryCount||0);return`<section class="panel library-toolbar"><div class="panel-head"><div><div class="panel-title">App Library</div><div class="panel-sub">${fmt(t.total||S.data?.counts?.total||0)} Android records · 20 apps per page.</div></div><div class="library-head-actions"><button class="btn primary" id="addApk">${icon('plus')} Add APK</button></div></div><div class="library-filterbar"><div class="library-tabs"><button class="library-tab ${f.sort==='latest'?'active':''}" data-sort="latest">Latest</button><button class="library-tab ${f.sort==='popular'?'active':''}" data-sort="popular">Popular</button><button class="library-tab ${f.sort==='trending'?'active':''}" data-sort="trending">Trending</button></div><div class="library-sections"><button class="section-chip ${f.section==='all'?'active':''}" data-section="all">All</button><button class="section-chip ${f.section==='apps'&&!f.category?'active':''}" data-section="apps">Apps</button><button class="section-chip ${f.section==='games'&&!f.category?'active':''}" data-section="games">Games</button></div><div class="searchbar library-search"><span class="search-icon">${icon('search')}</span><input class="input" id="librarySearch" value="${esc(f.q)}" placeholder="Search app, game, package or developer"></div></div>${isAdmin()?`<div class="library-tools"><div class="taxonomy-tools"><div><b>Category structure</b><div class="helper">${saved?`${fmt(count)} saved categories · ${fetch.verified?'Verified source structure':'Source completeness not certified'}`:fetch.status==='fetching'?'Fetching categories…':fetch.status==='failed'?'Last fetch failed. Saved categories are unchanged.':fetch.status==='partial'?'Partial fetch. Saved categories are retained.':fetch.status==='interrupted'?'Last fetch was interrupted. Saved categories are retained.':'Not fetched yet'}</div>${fetch.lastError?`<div class="helper text-error">${esc(fetch.lastError)}</div>`:''}</div><button class="btn" id="syncStructure" ${fetch.status==='fetching'?'disabled':''}>${saved?'Refresh Categories':'Fetch Categories'}</button></div><div class="library-tools-divider"></div><div class="library-import-head"><div><b>LiteAPKs Import</b><div class="helper">Manual only. Choose a batch size; Appbit will not start another import automatically.</div></div><button class="btn" id="toggleImport" aria-expanded="${S.importOpen}">${S.importOpen?'Hide controls':'Import Controls'}</button></div><div id="libraryImportBody" ${S.importOpen?'':'hidden'}>${importControls()}</div></div>`:''}</section>`}
function categorySidebar(){const f=S.library,t=S.taxonomy||{},cats=Array.isArray(t.categories)?t.categories:[];const row=(label,count,section,slug='',sub=false,depth=0)=>`<button class="category-item ${sub?'subcategory':''} ${(f.section===section||section==='all'&&f.section==='all')&&f.category===slug?'active':''}" data-cat-section="${section}" data-category="${esc(slug)}" style="--category-depth:${depth}"><span>${esc(label)}</span><b>${fmt(count)}</b></button>`;const tree=(section,parent,depth=0,seen=new Set())=>cats.filter(c=>c.section===section&&c.parentSlug===parent&&!seen.has(c.slug)).map(c=>{const next=new Set(seen);next.add(c.slug);return row(c.name,c.count,section,c.slug,true,depth)+tree(section,c.slug,depth+1,next)}).join('');return`<aside class="category-sidebar"><div class="category-title">LiteAPKs Categories</div>${row('All Library',t.total||0,'all','')}<div class="category-group"><div class="category-main-row">${row('Apps',t.sections?.apps||0,'apps','')}</div><div class="subcategory-list">${tree('apps','apps')}</div></div><div class="category-group"><div class="category-main-row">${row('Games',t.sections?.games||0,'games','')}</div><div class="subcategory-list">${tree('games','games')}</div></div></aside>`}
function pageButtons(){const p=S.pagination||{},pages=Math.max(1,Number(p.pages||1)),current=Math.max(1,Number(p.page||1));if(pages<=1)return'';const nums=new Set([1,pages,current-2,current-1,current,current+1,current+2]);const list=[...nums].filter(n=>n>=1&&n<=pages).sort((a,b)=>a-b);let last=0;const buttons=[];for(const n of list){if(last&&n-last>1)buttons.push('<span class="page-gap">…</span>');buttons.push(`<button class="page-btn ${n===current?'active':''}" data-page="${n}">${n}</button>`);last=n}return`<nav class="pagination" aria-label="App pages"><button class="page-btn page-arrow" data-page="${Math.max(1,current-1)}" ${current===1?'disabled':''}>‹</button>${buttons.join('')}<button class="page-btn page-arrow" data-page="${Math.min(pages,current+1)}" ${current===pages?'disabled':''}>›</button></nav>`}
function importControls(){const st=S.importState||{},active=['discovering','running'].includes(st.status),total=Number(st.total_count||0),processed=Number(st.processed_count||0),percent=total?Math.min(100,Math.round(processed/total*100)):0;return`<div class="import-control-grid"><label class="control-field"><span>Source pages to process</span><input class="input" id="syncLimit" type="number" min="1" max="50000" step="1" value="10"></label><label class="control-field"><span>Import mode</span><select class="input" id="syncMode"><option value="new">Add new apps</option><option value="daily">Refresh recent source apps</option><option value="full">Refresh source catalog</option></select></label><div class="quick-limits"><button class="btn tiny" data-limit="5">5</button><button class="btn tiny" data-limit="10">10</button><button class="btn tiny" data-limit="20">20</button></div><div class="control-actions"><button class="btn primary" id="syncNow" ${active?'disabled':''}>Start Import</button><button class="btn danger" id="stopSync" ${active?'':'disabled'}>Stop</button></div></div><div class="import-status" id="importStatus" aria-live="polite">${importStatusHtml(st)}</div>`}
function importStatusHtml(st={}){const total=Number(st.total_count||0),processed=Number(st.processed_count||0),percent=total?Math.min(100,Math.round(processed/total*100)):0;return`<div class="import-status-line"><b>${esc(st.status||'idle')}</b><span>${fmt(processed)} / ${fmt(total)} processed</span><span>${fmt(st.inserted_count)} added</span><span>${fmt(st.updated_count)} refreshed</span><span>${fmt(st.failed_count)} failed</span></div><div class="progress"><span style="width:${percent}%"></span></div>${st.last_error?`<div class="notice ${st.status==='paused'?'amber':'error'}">${esc(st.last_error)}</div>`:''}<div class="helper">A selected limit is the maximum number of source pages to process, not a guarantee that every page is a new app. Existing records and failed pages are reported separately.</div>`}
function updateImportState(st){S.importState=st;const box=$('#importStatus');if(box)box.innerHTML=importStatusHtml(st);const active=['discovering','running'].includes(st.status);if($('#syncNow'))$('#syncNow').disabled=active;if($('#stopSync'))$('#stopSync').disabled=!active}
function scheduleImportPoll(){clearTimeout(S.importTimer);if(!['running','discovering'].includes(S.importState?.status))return;S.importTimer=setTimeout(async()=>{try{const d=await API('/api/resolver/state');const previous=S.importState?.status;updateImportState(d.state||{});if(['running','discovering'].includes(S.importState.status))scheduleImportPoll();else if(['running','discovering'].includes(previous)){await refreshBootstrap();if(S.tab==='library'){await loadLibrary();renderLibrary()}}}catch(e){toast(e.message,'error')}},2000)}
async function startManualImport(){const input=$('#syncLimit'),limit=Number(input?.value),mode=$('#syncMode')?.value||'new';if(!Number.isSafeInteger(limit)||limit<1||limit>50000)return toast('Enter a whole number from 1 to 50,000.','warning');const b=$('#syncNow');b.disabled=true;try{const d=await API('/api/resolver/sync',{method:'POST',body:JSON.stringify({mode,limit})});updateImportState(d.state||{});scheduleImportPoll();toast('Manual import started.')}catch(e){toast(e.message,'error');b.disabled=false}}
async function stopManualImport(){try{const d=await API('/api/resolver/stop',{method:'POST',body:'{}'});clearTimeout(S.importTimer);updateImportState(d.state||{});toast('Import stopped.')}catch(e){toast(e.message,'error')}}
function bindImportControls(){document.querySelectorAll('[data-limit]').forEach(b=>b.onclick=()=>{$('#syncLimit').value=b.dataset.limit});$('#syncNow').onclick=startManualImport;$('#stopSync').onclick=stopManualImport;updateImportState(S.importState||{})}

function libraryResults(){const p=S.pagination||{},cat=selectedCategory(),sectionLabel=S.library.section==='games'?'Games':S.library.section==='apps'?'Apps':'All Apps & Games',viewLabel=cat?.name||sectionLabel,title=S.library.sort==='popular'?`Popular · ${viewLabel}`:S.library.sort==='trending'?`Trending · ${viewLabel}`:viewLabel;return`<section class="panel library-results"><div class="library-results-head"><div><div class="panel-title">${esc(title)}</div><div class="panel-sub">Showing ${fmt(p.from||0)}–${fmt(p.to||0)} of ${fmt(p.total||0)} records. Page ${fmt(p.page||1)} of ${fmt(p.pages||1)}.</div></div>${S.library.category?`<button class="btn tiny" id="clearCategory">Back to ${esc(sectionLabel)}</button>`:''}</div><div class="app-grid library-card-grid">${S.apps.length?S.apps.map(appRow).join(''):'<div class="empty app-grid-empty">No apps match this category.</div>'}</div><div class="library-pagination-row"><span>20 apps per page · ${fmt(p.total||0)} in this view</span>${pageButtons()}</div></section>`}
function renderLibrary(){const c=$('#content');c.innerHTML=libraryToolbar()+`<div class="library-layout">${categorySidebar()}${libraryResults()}</div>`;$('#addApk').onclick=()=>go('add');if($('#toggleImport'))$('#toggleImport').onclick=()=>{S.importOpen=!S.importOpen;$('#libraryImportBody').hidden=!S.importOpen;$('#toggleImport').textContent=S.importOpen?'Hide controls':'Import Controls';$('#toggleImport').setAttribute('aria-expanded',String(S.importOpen));if(S.importOpen)bindImportControls()};if($('#syncStructure'))$('#syncStructure').onclick=async()=>{const previous=S.taxonomy.fetch||{},force=['complete','existing','partial','interrupted'].includes(previous.status);if(force&&!confirm('Refresh the saved LiteAPKs category structure? Existing categories will be kept if the source is unavailable.'))return;const b=$('#syncStructure');b.disabled=true;b.textContent='Fetching categories…';try{const d=await API('/api/taxonomy/refresh',{method:'POST',body:JSON.stringify({force})});toast(d.skipped?'Saved categories retained':`Saved ${fmt(d.sourceCategoryCount)} source categories`);await loadLibrary();renderLibrary()}catch(e){toast(e.message,'error');await loadTaxonomy();renderLibrary()}};document.querySelectorAll('[data-sort]').forEach(b=>b.onclick=async()=>{S.library.sort=b.dataset.sort;S.library.page=1;await go('library')});document.querySelectorAll('[data-section]').forEach(b=>b.onclick=async()=>{S.library.section=b.dataset.section;S.library.category='';S.library.page=1;await go('library')});document.querySelectorAll('[data-cat-section]').forEach(b=>b.onclick=async()=>{S.library.section=b.dataset.catSection;S.library.category=b.dataset.category||'';S.library.page=1;await go('library')});document.querySelectorAll('[data-page]').forEach(b=>b.onclick=async()=>{if(b.disabled)return;S.library.page=Number(b.dataset.page)||1;await go('library');window.scrollTo({top:0,behavior:'smooth'})});if($('#clearCategory'))$('#clearCategory').onclick=async()=>{S.library.category='';S.library.page=1;await go('library')};let timer=null;$('#librarySearch').oninput=e=>{clearTimeout(timer);const value=e.target.value;timer=setTimeout(async()=>{S.library.q=value.trim();S.library.page=1;await go('library',{replace:true})},450)};if(S.importOpen)bindImportControls();bindRows(c)}
function renderPublishing(){const c=$('#content');c.innerHTML=appPanel('Public Apps',`${S.apps.length} public app${S.apps.length===1?'':'s'} in Appbit.`,S.apps,'No apps are public yet.');bindRows(c)}
function field(label,value,copy=''){return`<div class="field"><div class="field-label">${esc(label)}</div><div class="field-value">${value||'N/A'}${copy?` <button class="btn tiny" data-copy="${esc(copy)}">Copy</button>`:''}</div></div>`}
function detailHtml(x){const m=x.sourceMeta||{},media=x.media||{},shots=Array.isArray(m.screenshots)&&m.screenshots.length?m.screenshots.slice(0,24):(Array.isArray(media.screenshots)?media.screenshots.slice(0,24):[]),hasIcon=Boolean(m.iconUrl||media.iconUrl),hasCover=Boolean(m.coverImageUrl||media.coverImageUrl),direct=safeUrl(m.directDownloadUrl),play=verifiedPlayUrl(m.playStoreUrl)||verifiedPlayUrl(x.officialUrl);return`<div class="app-workspace"><div class="workspace-breadcrumb"><button class="btn" id="closeDetail">← Back to App Library</button><span>${esc(x.name)}</span></div><section class="panel app-detail-panel"><div class="app-detail-header"><div class="app-detail-heading"><div class="detail-title">${esc(x.name)}</div><div class="form-row"><span class="code">v${esc(x.version||'—')}</span><span class="status ${x.published?'published':'draft'}">${x.published?'Published':'Draft'}</span>${x.updateAvailable?`<span class="status update">Update ${esc(x.latestVersion||'available')}</span>`:''}</div><div class="panel-sub">${esc(x.sourcePackageId||x.packageId)} · Android APK</div></div><div class="form-row"><button class="btn" id="refreshApp">Refresh Metadata</button><button class="btn" id="refreshAppMedia">Refresh Media</button>${x.updateAvailable?'<button class="btn" id="markUpdated">Mark Updated</button>':''}<button class="btn ${x.published?'':'primary'}" id="togglePublish">${x.published?'Unpublish':'Publish'}</button></div></div><div class="app-detail-body"><div id="detailMessage" aria-live="polite"></div>${hasCover?`<div class="apk-cover-hero"><img src="/api/apps/${x.id}/media/cover?inline=1" alt="${esc(x.name)} cover"></div>`:`<div class="apk-cover-hero missing-cover"><span>No cover image stored</span><span>Use Refresh Media to check the source again.</span></div>`}${x.updateAvailable?`<div class="notice amber"><b>Source update detected.</b> ${esc(x.updateError||'Review the latest version before publishing.')}</div>`:''}<div class="android-detail-layout"><section class="android-detail-main"><h3 class="section-title">APK Metadata</h3><div class="fields android-fields">${field('App Name',esc(x.name))}${field('Developer',esc(x.developer||'Not reported'))}${field('Category',esc(x.category||'Other'))}${field('Section',esc((x.sourceSection||'apps').replace(/^./,c=>c.toUpperCase())))}${field('Version',esc(x.version||'Not reported'))}${field('App Size',bytes(x.fileSizeBytes))}${field('Requires Android',esc(x.minimumOsVersion||'Not reported'))}${field('APK Type',esc(x.apkType||m.apkType||'APK'))}${field('Architecture',esc(x.architecture||'Android'))}${field('Rating',x.ratingValue==null?'Not reported':`${esc(x.ratingValue)}/5`)}${field('Downloads',x.downloadCount==null?'Not reported':fmt(x.downloadCount))}${field('Updated Date',date(x.sourceUpdatedAt))}</div><h3 class="section-title section-gap">Links</h3><div class="fields android-link-fields">${field('Official Play Store',play?`<a href="${esc(play)}" target="_blank" rel="noopener noreferrer">Open Google Play ↗</a>`:'Not available',play)}${field('Direct APK Link',direct?`<a href="${esc(direct)}" target="_blank" rel="noopener noreferrer">Open file ↗</a>`:'Resolve when needed',direct)}</div><div class="form-row section-gap"><button class="btn primary" id="resolveDownload">Resolve Direct Download</button></div><div class="section-heading-row"><h3 class="section-title">Description</h3><button class="btn tiny" data-copy-target="appDescription">Copy Description</button></div><div class="desc app-description" id="appDescription">${esc(x.description||'No description was reported by the source.')}</div></section><aside class="apk-media-card"><div class="apk-media-head"><div><div class="section-title" style="margin:0">APK Media</div><div class="helper">Cover, icon, and screenshots from the saved APK metadata.</div></div></div><div class="apk-icon-wrap">${hasIcon?`<img class="apk-icon-preview" src="/api/apps/${x.id}/media/icon?inline=1" alt="${esc(x.name)} icon">`:'<div class="apk-icon-empty">No icon</div>'}</div><div class="apk-media-actions">${hasIcon?`<a class="btn" href="/api/apps/${x.id}/media/icon">Download Icon</a>`:''}${hasCover?`<a class="btn" href="/api/apps/${x.id}/media/cover">Download Cover</a>`:''}${hasIcon||hasCover||shots.length?`<a class="btn primary" href="/api/apps/${x.id}/media.zip">Download Media ZIP</a>`:''}<button class="btn" id="refreshMediaSide">Refresh Media</button></div><div class="helper">${shots.length} screenshot${shots.length===1?'':'s'} available</div></aside></div><div class="section-heading-row"><h3 class="section-title">Screenshots</h3></div>${shots.length?`<div class="apk-screenshot-grid">${shots.map((_,i)=>`<a class="apk-shot" href="/api/apps/${x.id}/media/screenshot/${i}"><img src="/api/apps/${x.id}/media/screenshot/${i}?inline=1" loading="lazy" alt="Screenshot ${i+1}"><span>Screenshot ${i+1}</span></a>`).join('')}</div>`:'<div class="empty compact-empty">No screenshots found. Use Refresh Media to check again.</div>'}<h3 class="section-title section-gap">Version History</h3><div class="versions compact-versions">${(x.versions||[]).length?(x.versions||[]).map(v=>`<div class="version-row"><div><b>${esc(v.version)}</b><div class="helper">${date(v.updatedDate)} · ${esc(v.apkType||x.apkType||'APK')}</div></div></div>`).join(''):'<div class="empty compact-empty">No previous versions recorded.</div>'}</div></div></section></div>`}
function verifiedPlayUrl(v){try{const u=new URL(v);return u.protocol==='https:'&&u.hostname==='play.google.com'&&u.pathname==='/store/apps/details'&&u.searchParams.get('id')?u.toString():''}catch{return''}}

async function openDetail(id,opts={}){id=Number(id);if(!Number.isSafeInteger(id)||id<1)return go('library');const seq=++S.routeSeq;const returnUrl=opts.returnUrl||(!['detail','add'].includes(S.tab)?location.pathname+location.search:S.detailReturn||'/library');if(S.detail?.id!==id&&S.detail)await releaseActiveDetail();S.tab='detail';S.detailReturn=returnUrl;$('#sidebar')?.classList.remove('open');updateHeader();if(opts.history!==false)setRoute(`/apps/${id}`,{state:{appbitDetail:true,returnUrl}});$('#content').innerHTML='<div class="notice">Opening APK workspace…</div>';try{const claim=await API(`/api/apps/${id}/claim`,{method:'POST',body:'{}'});if(seq!==S.routeSeq){await API(`/api/apps/${id}/release`,{method:'POST',body:'{}'}).catch(()=>{});return}const d=await API(`/api/apps/${id}`);if(seq!==S.routeSeq){await API(`/api/apps/${id}/release`,{method:'POST',body:'{}'}).catch(()=>{});return}S.detail=d.app;S.detail.claim=claim.claim;renderDetail();startHeartbeat(id);window.scrollTo(0,0)}catch(e){if(e.status===423&&e.data?.claim)return showLock(id,e.data.claim);if(seq===S.routeSeq){await API(`/api/apps/${id}/release`,{method:'POST',body:'{}'}).catch(()=>{});}if(seq===S.routeSeq)$('#content').innerHTML=`<section class="panel"><div class="panel-body"><div class="notice error">${esc(e.message)}</div><button class="btn" id="closeDetail">Back to App Library</button></div></section>`;if($('#closeDetail'))$('#closeDetail').onclick=closeDetail}}
function renderDetail(){const x=S.detail;if(!x)return;$('#content').innerHTML=detailHtml(x);$('#closeDetail').onclick=closeDetail;const action=async(button,task)=>{if(button)button.disabled=true;const msg=$('#detailMessage');if(msg)msg.innerHTML='<div class="notice">Working…</div>';try{await task();}catch(e){if(msg)msg.innerHTML=`<div class="notice error">${esc(e.message)}</div>`;toast(e.message,'error');if(button)button.disabled=false}};const reload=async()=>{const d=await API(`/api/apps/${x.id}`);S.detail=d.app;renderDetail();await refreshBootstrap()};$('#refreshApp').onclick=()=>action($('#refreshApp'),async()=>{await API(`/api/apps/${x.id}/refresh`,{method:'POST',body:'{}'});await reload();toast('APK metadata refreshed')});const refreshMedia=button=>action(button,async()=>{const d=await API(`/api/apps/${x.id}/media/refresh`,{method:'POST',body:'{}'});await reload();toast(`Media refreshed: ${d.screenshots} screenshots, ${d.cover?'cover found':'no cover reported'}`)});$('#refreshAppMedia').onclick=()=>refreshMedia($('#refreshAppMedia'));if($('#refreshMediaSide'))$('#refreshMediaSide').onclick=()=>refreshMedia($('#refreshMediaSide'));$('#togglePublish').onclick=()=>action($('#togglePublish'),async()=>{await API(`/api/apps/${x.id}/toggle-published`,{method:'POST',body:'{}'});await reload();toast(x.published?'Moved back to draft':'App published')});if($('#markUpdated'))$('#markUpdated').onclick=()=>action($('#markUpdated'),async()=>{await API(`/api/apps/${x.id}/mark-updated`,{method:'POST',body:'{}'});await reload();toast('App marked updated')});$('#resolveDownload').onclick=()=>action($('#resolveDownload'),async()=>{const d=await API(`/api/apps/${x.id}/download/resolve`,{method:'POST',body:'{}'});if(d.url)window.open(d.url,'_blank','noopener');else toast('Direct APK URL was not resolved')});bindCopy($('#content'))}
async function copyText(value){if(navigator.clipboard?.writeText)await navigator.clipboard.writeText(value);else{const el=document.createElement('textarea');el.value=value;el.style.position='fixed';el.style.opacity='0';document.body.appendChild(el);el.select();const ok=document.execCommand('copy');el.remove();if(!ok)throw new Error('Clipboard is unavailable.')}toast('Copied')}
function bindCopy(root){root.querySelectorAll('[data-copy],[data-copy-target]').forEach(b=>b.onclick=()=>{const value=b.dataset.copyTarget?document.getElementById(b.dataset.copyTarget)?.textContent:b.dataset.copy;copyText(value||'').catch(()=>toast('Copy failed','error'))})}

function startHeartbeat(id){stopHeartbeat();S.heartbeat=setInterval(async()=>{try{await API(`/api/apps/${id}/heartbeat`,{method:'POST',body:'{}'})}catch{}},30000)}function stopHeartbeat(){if(S.heartbeat){clearInterval(S.heartbeat);S.heartbeat=null}}
async function closeDetail(){const back=S.detailReturn||'/library';const fromHistory=history.state?.appbitDetail&&history.state?.returnUrl;if(fromHistory&&history.length>1){history.back();return}await navigatePath(back,{replace:true})}
async function navigatePath(path,{replace=false}={}){const u=new URL(path,location.origin);setRoute(u.pathname+u.search,{replace});return routeLocation()}

function showLock(id,claim){$('#content').innerHTML=`<section class="panel app-detail-panel"><div class="panel-head"><div><div class="panel-title">App is currently open</div><div class="panel-sub">${esc(claim.name)} is working on this APK record.</div></div><button class="btn" id="closeLock">Back to Library</button></div><div class="panel-body"><div class="notice amber">The work lock is temporary and prevents conflicting edits.</div>${isAdmin()?`<div class="form-row section-gap"><button class="btn danger" id="forceRelease">Force Release</button><button class="btn primary" id="takeOver">Take Over</button></div>`:''}</div></section>`;$('#closeLock').onclick=closeDetail;if($('#forceRelease'))$('#forceRelease').onclick=async()=>{await API(`/api/apps/${id}/release`,{method:'POST',body:JSON.stringify({force:true})});toast('Work lock released');await go('library')};if($('#takeOver'))$('#takeOver').onclick=async()=>{await API(`/api/apps/${id}/takeover`,{method:'POST',body:'{}'});await openDetail(id,{history:false})}}

function openImportPage(){return go('add')}
function renderImportPage(){const c=$('#content');c.innerHTML=`<div class="app-workspace"><div class="workspace-breadcrumb"><button class="btn" id="importClose">← Back to App Library</button></div><section class="panel app-detail-panel"><div class="panel-head"><div><div class="panel-title">Add APK</div><div class="panel-sub">Add a single Android app using its public LiteAPKs detail page URL.</div></div></div><div class="panel-body"><form id="importForm" class="stack-form"><label>APK source page URL<input class="input wide" id="sourceUrl" type="url" required placeholder="https://liteapks.com/example-app.html" autocomplete="off"></label><div class="helper">This is a manual import. Only public source pages are fetched; access restrictions are not bypassed.</div><div id="importMsg" aria-live="polite"></div><div class="form-row section-gap"><button class="btn primary" id="importApp" type="submit">Resolve & Add</button><button class="btn" id="importCancel" type="button">Cancel</button></div></form></div></section></div>`;$('#importClose').onclick=()=>go('library');$('#importCancel').onclick=()=>go('library');$('#importForm').onsubmit=async e=>{e.preventDefault();const b=$('#importApp');b.disabled=true;$('#importMsg').innerHTML='<div class="notice">Resolving APK metadata…</div>';try{const d=await API('/api/apps/import',{method:'POST',body:JSON.stringify({sourcePageUrl:$('#sourceUrl').value})});toast(`${d.app.name} added`);await refreshBootstrap();await go('library');await openDetail(d.app.id)}catch(e){$('#importMsg').innerHTML=`<div class="notice error">${esc(e.message)}</div>`;b.disabled=false}}}

async function startUpdateScan(){const b=$('#scanUpdates'),limit=Math.max(1,Math.min(50000,Number($('#updateLimit')?.value||20)));if(b)b.disabled=true;try{await API('/api/updates/start',{method:'POST',body:JSON.stringify({limit})});toast(`Update scan started for up to ${limit} apps`);pollUpdateScan()}catch(e){toast(e.message,'error');if(b)b.disabled=false}}
async function stopUpdateScan(){clearTimeout(S.updateTimer);try{await API('/api/updates/stop',{method:'POST',body:'{}'});toast('Update scan stopped');if(S.tab==='updates')await renderUpdateCenter()}catch(e){toast(e.message,'error')}}
async function pollUpdateScan(){clearTimeout(S.updateTimer);try{const d=await API('/api/updates/step',{method:'POST',body:'{}'});const st=d.state||{};if(st.status==='running'){const p=$('#updateProgress');if(p)p.textContent=`${fmt(st.processed_count)} / ${fmt(st.total_count)} checked`;S.updateTimer=setTimeout(pollUpdateScan,1600)}else{toast(st.status==='stopped'?'Update scan stopped':`Update scan complete: ${fmt(st.update_count)} found`);await refreshBootstrap();if(S.tab==='updates'){await loadApps('updates');await renderUpdateCenter()}}}catch(e){toast(e.message,'error')}}
async function renderUpdateCenter(){const c=$('#content'),d=await API('/api/updates/state'),st=d.state||{};c.innerHTML=`<section class="panel control-panel"><div class="panel-head"><div><div class="panel-title">Update Center</div><div class="panel-sub">Manual update checks only. Appbit will not start a scan by itself.</div></div></div><div class="panel-body"><div class="control-grid"><label class="control-field"><span>Apps to check</span><input class="input" id="updateLimit" type="number" min="1" max="50000" value="${Math.max(1,Number(st.total_count||20))}"></label><div class="control-actions"><button class="btn primary" id="scanUpdates">${icon('refresh')} Start Scan</button><button class="btn danger" id="stopUpdates">Stop</button></div></div><div class="workspace-summary"><div><span>Status</span><b>${esc(st.status||'idle')}</b></div><div><span>Progress</span><b id="updateProgress">${fmt(st.processed_count)} / ${fmt(st.total_count)}</b></div><div><span>Updates</span><b>${fmt(st.update_count)}</b></div><div><span>Failed</span><b>${fmt(st.failed_count)}</b></div></div>${st.last_error?`<div class="notice error">${esc(st.last_error)}</div>`:''}</div></section>${appPanel('Updates Ready',`${S.apps.length} app${S.apps.length===1?'':'s'} currently have an update available.`,S.apps,'No app updates are waiting.')}`;$('#scanUpdates').onclick=startUpdateScan;$('#stopUpdates').onclick=stopUpdateScan;bindRows(c);if(st.status==='running')S.updateTimer=setTimeout(pollUpdateScan,1200)}
async function openNotifications(){if($('#notificationPanel'))return $('#notificationPanel').remove();document.body.insertAdjacentHTML('beforeend','<section class="notification-panel" id="notificationPanel"><div class="notification-head"><div><div class="notification-heading">Notifications</div><div class="notification-sub">Appbit workspace activity.</div></div><button class="btn icon-btn" id="notificationClose">×</button></div><div class="notification-list" id="notificationList"><div class="notification-empty">Loading…</div></div><div class="notification-foot"><button class="link-button" id="markAllNotifications">Mark all as read</button></div></section>');$('#notificationClose').onclick=()=>$('#notificationPanel').remove();$('#markAllNotifications').onclick=async()=>{await API('/api/notifications/read',{method:'POST',body:JSON.stringify({all:true})});await refreshBootstrap();$('#notificationPanel').remove()};try{const d=await API('/api/notifications?limit=30');$('#notificationList').innerHTML=d.items.length?d.items.map(n=>`<div class="notification-item ${n.isRead?'':'unread'}"><div class="notification-item-title">${esc(n.title)}</div><div class="notification-item-message">${esc(n.message||'')}</div><div class="notification-item-time">${date(n.createdAt)}</div></div>`).join(''):'<div class="notification-empty">No notifications yet.</div>'}catch(e){$('#notificationList').innerHTML=`<div class="notice error">${esc(e.message)}</div>`}}
async function renderSettings(){const c=$('#content');const [ud,bd]=await Promise.all([API('/api/users'),API('/api/backups/state')]);S.users=ud.users||[];const backup=bd.backup||{};c.innerHTML=`<section class="panel"><div class="panel-head"><div><div class="panel-title">Team</div><div class="panel-sub">Admin and Partner access.</div></div><button class="btn primary" id="addPartner">Add Partner</button></div><div class="team-grid">${S.users.map(u=>`<div class="team-card"><div class="logo-box logo-fallback">${esc((u.name||u.email).slice(0,1).toUpperCase())}</div><div class="team-copy"><b>${esc(u.name||u.email)}</b><span>${esc(u.email)}</span></div><span class="status ${u.active?'published':'draft'}">${u.roleLabel}</span>${u.role==='partner'?`<button class="btn tiny" data-status="${u.id}" data-active="${u.active?'0':'1'}">${u.active?'Disable':'Enable'}</button>`:''}</div>`).join('')}</div></section><section class="panel backup-panel"><div class="panel-head"><div><div class="panel-title">Backups</div><div class="panel-sub">Create, download, or restore Appbit Android data.</div></div><button class="btn primary" id="createBackup">Create Backup</button></div><div class="panel-body"><div class="backup-latest"><div><span>Latest backup</span><b>${esc(backup.last?.filename||'None yet')}</b><small>${backup.last?.createdAt?date(backup.last.createdAt):'No backup created yet'}</small></div>${backup.last?.id?`<a class="btn" href="/api/backups/${backup.last.id}/download">Download</a>`:''}</div><label class="upload-box" for="restoreFile"><span class="upload-title">Upload backup JSON</span><span class="upload-help">Choose an Appbit backup file to restore.</span><input id="restoreFile" type="file" accept="application/json,.json"></label><div class="form-row backup-actions"><button class="btn danger" id="restoreBackup">Restore Uploaded Backup</button></div><div id="backupMsg"></div></div></section><section class="panel"><div class="panel-head"><div><div class="panel-title">Data Maintenance</div><div class="panel-sub">Dangerous actions are kept separate from normal publishing controls.</div></div></div><div class="panel-body"><div class="form-row"><button class="btn" id="clearDrafts">Clear Draft Apps</button><button class="btn danger" id="resetData">Reset APK Data</button></div></div></section>`;$('#addPartner').onclick=openPartnerModal;document.querySelectorAll('[data-status]').forEach(b=>b.onclick=async()=>{await API(`/api/users/${b.dataset.status}/status`,{method:'POST',body:JSON.stringify({active:b.dataset.active==='1'})});toast('Partner updated');renderSettings()});$('#createBackup').onclick=async()=>{try{await API('/api/backups/create',{method:'POST',body:'{}'});toast('Appbit backup created');renderSettings()}catch(e){toast(e.message,'error')}};$('#restoreBackup').onclick=async()=>{const f=$('#restoreFile').files[0];if(!f)return toast('Choose a backup file','warning');if(!confirm('Restore this Appbit backup? Current APK data will be replaced.'))return;try{$('#backupMsg').innerHTML='<div class="notice">Uploading and validating backup…</div>';const d=await API('/api/backups/restore',{method:'POST',headers:{'content-type':'application/octet-stream'},body:f});toast(`Restored ${fmt(d.restoredApps)} apps`);await refreshBootstrap();go('dashboard')}catch(e){$('#backupMsg').innerHTML=`<div class="notice error">${esc(e.message)}</div>`}};$('#clearDrafts').onclick=async()=>{if(!confirm('Delete all draft APK apps?'))return;await API('/api/maintenance/clear-drafts',{method:'POST',body:'{}'});toast('Draft apps cleared');await refreshBootstrap();go('dashboard')};$('#resetData').onclick=async()=>{if(!confirm('Delete all APK app data from Appbit?'))return;await API('/api/maintenance/reset',{method:'POST',body:'{}'});toast('APK data reset');await refreshBootstrap();go('dashboard')}}
function openPartnerModal(){document.body.insertAdjacentHTML('beforeend',`<div class="modal-wrap" id="partnerWrap"><div class="modal" style="max-width:580px"><div class="modal-head"><div class="detail-title">Add Partner</div><button class="btn icon-btn" id="partnerClose">${icon('close')}</button></div><div class="panel-body"><div class="stack-form"><label>Name<input class="input" id="partnerName"></label><label>Email<input class="input" id="partnerEmail" type="email"></label><label>Password<input class="input" id="partnerPassword" type="password" minlength="10"></label><button class="btn primary" id="savePartner">Create Partner</button><div id="partnerMsg"></div></div></div></div></div>`);$('#partnerClose').onclick=()=>$('#partnerWrap').remove();$('#savePartner').onclick=async()=>{try{await API('/api/users/partner',{method:'POST',body:JSON.stringify({name:$('#partnerName').value,email:$('#partnerEmail').value,password:$('#partnerPassword').value})});$('#partnerWrap').remove();toast('Partner created');renderSettings()}catch(e){$('#partnerMsg').innerHTML=`<div class="notice error">${esc(e.message)}</div>`}}}
async function openHealth(){document.body.insertAdjacentHTML('beforeend',`<div class="modal-wrap" id="healthWrap"><div class="modal" style="max-width:680px"><div class="modal-head"><div class="detail-title">System Health</div><button class="btn icon-btn" id="healthClose">${icon('close')}</button></div><div class="panel-body" id="healthBody">Loading…</div></div></div>`);$('#healthClose').onclick=()=>$('#healthWrap').remove();try{const d=await API('/api/health');$('#healthBody').innerHTML=d.checks.map(x=>`<div class="health-row"><span class="health-dot ${x.status==='fail'?'fail':''}"></span><div><b>${esc(x.name)}</b><div class="helper">${esc(x.detail)}</div></div></div>`).join('')}catch(e){$('#healthBody').innerHTML=`<div class="notice error">${esc(e.message)}</div>`}}
async function init(){try{await bootstrap();shell();await routeLocation();S.notificationTimer=setInterval(refreshBootstrap,30000);API('/api/resolver/state').then(d=>{S.importState=d.state||{};scheduleImportPoll()}).catch(()=>{})}catch(e){app.innerHTML=`<div class="boot"><div><b>Appbit could not load.</b><div style="margin-top:8px;color:#ff453a">${esc(e.message)}</div></div></div>`}}
window.addEventListener('pagehide',()=>{if(S.detail?.id&&S.csrf)fetch(`/api/apps/${S.detail.id}/release`,{method:'POST',keepalive:true,credentials:'same-origin',headers:{'content-type':'application/json','x-csrf-token':S.csrf},body:'{}'}).catch(()=>{})});
window.addEventListener('popstate',()=>routeLocation().catch(e=>toast(e.message,'error')));
init();
})();
